) AS (
  VALUES 
    (164::BIGINT, 'No es necesario ver las películas para hacer el centro, la cámara encendida en todo momento es muy importante, no deja tareas, utiliza todos los minutos de la clase, demasiado sencillo pasar el curso. Súper interesante y llamativo también.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-10-26T00:00:00+00:00'::TIMESTAMPTZ, '14cd6e2c0379377ce1972457c8b15fd19343c5b529d017874b00eaf55dfa86de'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'El curso puede resultar aburrido, sin embargo ella deja trabajos vacilones como preparaciones para debates que lo vuelven entretenido. Hay muchas tareas sencillas y hay varias clases donde solo se hace una presentación de 20 minutos y ya. Además, es la única profe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, '520b9cf1c05cb315da8f2892345ea986efac1cb65798b934f2ec534d22369582'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'Asistencia obligatoria y cámara encendida. Muy buena profe y el curso es muy interesante y es muy fácil y no hace falta prepararse para la clase, pone 100 a todo mientras participe en la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2026-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'e3de784de6e0538eed162bc7ca2500efad4400af5964054e8e781a1984713383'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'El curso más aburrido de la carrera, es un curso de inglés más con temas que poco tiene que ver con la carrera. Hay bastantes exposiciones donde si califica un toque más duro que en lo demás'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'b13767eca5360885e8e57570dbf2d8f1249438b85e6a917391467d12f2eabf09'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'La materia es como un curso normal de inglés. Ella deja muchos trabajos y hay bastantes exposiciones(lo normal en un curso de inglés). Ella como persona y profe es excelente hace las clases interesantes, es estricta eso si, se aprende muchísimo no solo inglés sino de la carrera(enfatizado en CE obv)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '503f761f55462e4ae8a594dc19afc721a7bd2084c3d4fdc6a826f3fde867808e'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'Es una excelente profe y persona. Las clases son muy interactivas y busca que los estudiantes estén participando constantemente. Con un poco de dedicación se pasa super sencillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'e151089fd4c6e1f865525f6725e39fa759ece162590b57d89552c6f39eab4cad'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'Es una gran profesora, la materia es un curso de inglés normal en el cual se debe exponer, conversar y realizar actividades típicas. Es un poco estricta, lo usual, pero es una gran persona a su vez que está dispuesta a ayudar siempre.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '45461f311a8c016f803290f577913b59d3647d30a9ad590af2ee181ac247d826'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'Es estricta, pero se aprende mucho. Con otros docentes las clases eran muy fáciles y no daban completamente las lecciones. Ella exige y, en mi caso subí el nivel de ingles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-10-19T00:00:00+00:00'::TIMESTAMPTZ, '40f77635ca0f0b91d6cb2b99ea7f92af48367454c44284af0e0aa7129975ca1b'::TEXT, ARRAY[2433]::BIGINT[]),
    (164::BIGINT, 'Es un amor de profe, el curso es uno de inglés más, obvio le va a tocar hablar en ingles en frente de la clase, es importante ir a clase pues muchas evaluaciones se hacen ahí.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'ec3cc0d6f1990a91c3a66f176cfa2eafbba654910fe5b2df853f64c057c311a6'::TEXT, ARRAY[2976]::BIGINT[]),
    (164::BIGINT, 'Muy buena profe que hace que el centro además de no ser pesado sea entretenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'e058c8f9a1e279a234cba57c310c9f879394a8b009ffb6d72cb502da35e620d1'::TEXT, ARRAY[648]::BIGINT[]),
    (164::BIGINT, 'Lo de esta tía no tiene ni pies ni cabeza, es simplemente la definición de perfección aerodinámica. Su manera de explicar sumado a su gran carisma y simpatía han hecho de este semestre una de las experiencias más fructíferas que haya experimentado en el período que llevo como estudiante. Cojonudo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-01-20T00:00:00+00:00'::TIMESTAMPTZ, '7c7aa02a7b90611f23dd7ad61635ea58e268097b51a63a11e2418d12460a9ab0'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Ayuda mucho a sus estudiantes, le gusta que los estudiantes entiendan la materia, aunque es bastante fácil. Es muy linda persona y se lleva bien con los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '463c7ee13b9cc97acf19cde88424ba79a202b1ed39b423264064e2ef26b99d07'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Es buena profe, explica bien, es buena gente, y el curso no es complicado. Sin embargo, realiza muchas actividades que no tienen evaluación, lo que me parece un poco extraño. De todas formas creo que si la recomendaría.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '6de3b620d3ac7f164e881b726d3923409015128f2d6bd8030dcd3fed754c800e'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Muy buena profe, comprende que todos tenemos niveles de inglés distintos. Lo único es que en todas las clases hay que participar con exposiciones, nada difíciles pero si llega a medio cansar. El proyecto es muy fácil y es muy respetuosa al corregirte'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9b268babc143c42a53c22476347f924438fdb4811bebc4387f7ce823ee0ed002'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Es muy buena profesora, hace las clases demasiado dinamicas, si no es bueno para hablar en publico siempre no matricule con ella porque es casi que siempre'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'eb53f6a9421ac1746561f8a906a7b4314db11a331d9a2fafd871ebd862e6ef26'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Muy recomendada, súper buena profe. Hace las clases muy dinámicas y deja bastantes tareas pero la mayoría son rápidas. Con que sea responsable y repase la materia, pasa bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5cda2ec29eaf1b8da7b967ba1f5d400d949035aed009468bc6f7d48e14149879'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Es una profe que da un ambiente muy bonito. Siempre hay actividades de practica en la clase (mayormente grupales) y el trabajo final es fácil. Ella es muy comprensiva y es muy amable. Muy recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '38f9891289803eabcd3c8f54d24083d5f33ad576eab8aaede1415d7179049760'::TEXT, ARRAY[2432]::BIGINT[]),
    (164::BIGINT, 'Virtual. Excelente profesora y atenta, deja muchos trabajos para realizar en clase pero no son muy complicados. Sus evaluaciones virtuales fueron por medio de un ambiente tranquilo y de confianza.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e3ecdbfda258086b31bfe2fb53f5625c3991a2cc0d1a61a5d64797c8a90285c7'::TEXT, ARRAY[2432]::BIGINT[]),
    (164::BIGINT, 'La profe es bastante ordenada con el curso y le gusta que haya mucha participación en la clase. Las tareas que deja son pesadas pero no extensas (se hacen en una hora).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '67dc54833055dc02fb0c68295e3ab7299c146855ea9ba70a5682efda4149ea31'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Es buena profe, las clases son dinámicas y explica muy bien. Le gusta el respeto, por lo que al hablar el idioma puedes sentirte más cómod@(si te resulta algo difícil). Exige cámara para quices o bien un vídeo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '6ff3ad03c1f1ffc856c30af250622d74aa01494c75a497fde4448ef6020d27a3'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'La profe es muy buena gente, explica súper bien, hace tareas y examenes fáciles que no quitan mucho tiempo, da puntos extras, pero es un poco intensa con el uso de la cámara durante los examenes, pero nada que de preocuparse.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '28316023a5f18202e3cf2945a0561d3049bdf9d627553e1ce52041669efe73e7'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Excelente persona y excelente profesora. La clase es corta y siempre se aprende algo útil incluso si ya sabe algo de inglés. Se preocupa por los estudiantes y se esfuerza por hacer actividades. Los trabajos son claros y no le quitan mucho tiempo. Matricule con ella, va a aprender.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-10T00:00:00+00:00'::TIMESTAMPTZ, '84183fec059b96011a72f89411bcff7776279cb93edae52b7e232713f903efef'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'En virtual. Solo haga todos los trabajos, la profe es pura vida, se pasa solo el curso, es muy ameno, solo haga las cosas a tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-11T00:00:00+00:00'::TIMESTAMPTZ, '104e7f212c428276ca84183787828b6b341cc4fc754073e951cf053a583d8c86'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'Las clases no son muy largas y son dinámicas. Las asignaciones son de acuerdo al curso, no son excesivamente complejas e incluso resultan interesantes. Es una belleza de persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-12-21T00:00:00+00:00'::TIMESTAMPTZ, '50f06d73a0140f9791c4bc799490c94995119e0f2ef956ee40eaa02a8cfc5eb3'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'La profe es excelente, buena gente. El CFH es interesante y deja 4 tareas simples que se pueden sacar en 1 hora o menos. No es necesario leerse las lecturas. La asistencia no es obligatoria'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a4256c49fc988581e0fc66d8c7dad9b55368273e06c022fb06df5d9b94239315'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'Facilita mucho el CFH, deja una tarea por sesión que es bastante sencilla de resolver y la asistencia no es obligatoria. Tampoco es necesario entrar a la clase para hacer la tarea y eso ayuda un montón'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, '189b2c7d05a5fdf0f40c81606b74cf13bb427795fb21ad9e6abfcc1a9f51ed43'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'Muy buena profe solo que si deja muchos trabajos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '16d59d822aab446ffd194816d3e6ccd9c342f8a9c1ccffa4168c47d950f77f77'::TEXT, ARRAY[2432]::BIGINT[]),
    (164::BIGINT, 'Yo llevé el CFH de manera virtual con ella, siempre termina una hora antes y deja una “tarea” corta y súper fácil que se puede hacer en esa hora. Hay que entregar 4 tareas y con eso se pasa el curso, no es necesario leer las obras ni asistir a las clases, súper recomendado el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-28T00:00:00+00:00'::TIMESTAMPTZ, '932f33ccac168131cdf0668285721a2f5978f1f2182a0e021662caafa95be9e9'::TEXT, ARRAY[799]::BIGINT[]),
    (164::BIGINT, 'Es una excelente profesora, algo seria pero luego se va a adaptando y nada fuera de lo normal. Si quiere pasar fácil y también aprender, meta con ella. Deja Online Lessons todas las semanas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '736bbec350ee07173d4a7bc797283df40ba9b7b5297f13661a8a2e4ff58494bc'::TEXT, ARRAY[539]::BIGINT[]),
    (164::BIGINT, 'Excelente profesora, se preocupa porque aprendan y entiendan los estudiantes, hace distintas dinámicas en clase, utiliza mucho los BreakRooms.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'd144213c2f5c3cf1e726d0bb7ae4f3b9c70fc84a51d1832db439f5e8a626148b'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Dele sin miedo al éxito con ella, no importa el curso que sea, es muy buena profesora y se preocupa por el desarrollo integral de los estudiantes, eso si tienen que ser muy participativos en clase porque a veces da créditos extra. La mejor profe que me pude haber topado en la virtualidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a1e796ef1fcb4d3735e064ecd0c783f50d1fa0cbc7527ac0624adec6aefb45d9'::TEXT, ARRAY[539]::BIGINT[]),
    (164::BIGINT, 'Excelente profe, dele con ella sin dudarlo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '2cb88086e4674ece142aa074f56eebbd34392306b17d9441d583ccd8c0841efa'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'En modalidad virtual, se preocupó por la integridad de los estudiantes, así como porque aprendiesen. Respondía rápido a las consultas por correo, y en clase le daba importancia a la participación. Bastante ameno llevar el curso con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '0ccc6b46d6d5ec13f6f0d3f12683f8f1f733d2c389b385c081cf59ee95568c79'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Sus clases son entretenidas y dinámicas, es una muy buena profe y cae muy bien, las clases son bastante relajantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '4272a2afa83f0d0207f123d38c0c913f90f7bbe4d8ca6393a34e1531ac07bb40'::TEXT, ARRAY[2379]::BIGINT[]),
    (164::BIGINT, 'Es una profesora excelente, hace las clases dinámicas. Usa muchas herramientas lo cual hace que la clase no sea aburrida. Ayuda y es muy amable. Definitivamente tomaría su clase de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '349da8fc65c26d4b5b63242d8994471b6a317e07dcea33e5d7d70827e97b6fae'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Es una profe super comprensiva, tiene su toque que algunas cosas pues si las califica justo, es buena opción.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '72ed19e8c1cf7cdae7fef0494ff396e980d2df78db62477f9c5b2057ca51724f'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Muy buena profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '02118c433347b2c3e6986590fafb029c82135afd23f4d1f496ca1279deb4d2ce'::TEXT, ARRAY[2432, 2379, 2433]::BIGINT[]),
    (164::BIGINT, 'Se pasa fácil y es buena nota pero hace la mayor parte de varas en grupo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '097b549d9c682732d4b3ef72c14f4fc9278e300978bc5ee50853dafb0907ddcf'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'Cae súper bien y se aprende bastante. Excelente profesora.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '46052425a7c17ce5a85accfef6ebde32b8a91db09585fd9d0a26775ce3f26d48'::TEXT, ARRAY[545]::BIGINT[]),
    (164::BIGINT, 'en los proyectos, quizes, etc, califica a todos por igual (no muy bueno en mi opnion)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '1e8d94a16078b05028cee3b6f94d68547aa86ea0e7c4d0499012fbbdd3ef4e18'::TEXT, ARRAY[545]::BIGINT[]),
